namespace CodeTamagotchi;
public record Q(string Text, string[] Options, int Answer, string Explain);
public record Level(string Title, string Theory, string Example, Q[] Qs, string Task, (string Pattern, string Msg)[] Checks, string Solution);
public static class Lessons
{
    public static readonly Level[] All =
    {
        new("Привет, консоль!", "Программа на C# — это набор команд. Чтобы вывести текст на экран, используем Console.WriteLine. Текст пишем в двойных кавычках, а каждую команду заканчиваем точкой с запятой.", "Console.WriteLine(\"Hello!\");",
            new Q[] { new("Как вывести текст на экран?", new[] { "Console.WriteLine(\"Hi\");", "print(\"Hi\");", "echo \"Hi\";", "Console.Show(\"Hi\");" }, 0, "В C# вывод делает Console.WriteLine(...)."),
                new("Чем заканчивается команда в C#?", new[] { "точкой", "точкой с запятой", "двоеточием", "ничем" }, 1, "Каждая команда завершается символом ; (точка с запятой)."),
                new("Как оформляется текст в WriteLine?", new[] { "в двойных кавычках", "в квадратных скобках", "в апострофах", "без знаков" }, 0, "Строки в C# заключают в двойные кавычки: \"текст\".") },
            "Выведи на экран слово Привет",
