            new Q[] { new("Какой тип хранит целые числа?", new[] { "string", "int", "bool", "double" }, 1, "int — целые числа, например 5 или -12."),
                new("Как правильно объявить строку?", new[] { "string name = \"Аня\";", "int name = \"Аня\";", "name = Аня;", "str name = 'Аня';" }, 0, "Тип string и текст в двойных кавычках."),
                new("Что может хранить bool?", new[] { "текст", "дробь", "true или false", "любое число" }, 2, "bool — логический тип: только true или false.") },
